WITH scored AS (SELECT id, order_id, product_id, quantity, unit_price, MIN(quantity) OVER (PARTITION BY order_id, product_id) AS order_id_min_quantity, AVG(unit_price) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS unit_price_avg_6_prior FROM order_items) SELECT id, order_id, product_id, unit_price, unit_price_avg_6_prior FROM scored;
